// Package store extension: novel-feature snapshot tables and the cross-engine
// backup_facts view. These are NOT generated by the Printing Press; they back
// servosity-pp-cli's transcendence commands (attention, drift, stale,
// backup-facts, stale-issues).
//
// Tables created on first call to EnsureNovelTables (idempotent):
//
//	attention_snapshots          — every `attention` run captures one row
//	                               per company that needs eyes-on, plus one
//	                               rollup row per snapshot via attention_runs.
//	attention_runs               — one row per attention call (run_id, ts,
//	                               total companies surfaced).
//	stale_backup_sets_snapshots  — one row per backup-set per `sync stale`
//	                               call (loaded from the CSV at /reports/stale-backup-sets/).
//	stale_runs                   — one row per stale-sync call.
//	dirty_repos_snapshots        — one row per dirty-repo per `sync dirty-repos` call.
//	dirty_runs                   — one row per dirty-repo-sync call.
//
// The attention/drift/stale commands query these snapshot tables; the
// `sync` extensions in commands populate them. This file owns the schema
// and the typed helpers; callers stay in `internal/cli/`.
package store

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

const novelSchemaSQL = `
CREATE TABLE IF NOT EXISTS attention_runs (
	run_id      TEXT PRIMARY KEY,
	ts          TEXT NOT NULL,
	total       INTEGER NOT NULL,
	reseller    TEXT
);
CREATE INDEX IF NOT EXISTS idx_attention_runs_ts ON attention_runs(ts);

CREATE TABLE IF NOT EXISTS attention_snapshots (
	run_id       TEXT NOT NULL,
	ts           TEXT NOT NULL,
	source       TEXT NOT NULL,           -- 'admin_attention' | 'dirty_repos' | 'draas_in_progress' | 'open_issues'
	company_id   TEXT NOT NULL DEFAULT '',
	company_name TEXT NOT NULL DEFAULT '',
	reseller_id  TEXT NOT NULL DEFAULT '',
	score        INTEGER NOT NULL DEFAULT 0,
	reason       TEXT NOT NULL DEFAULT '',
	raw          TEXT NOT NULL,           -- JSON of the source row
	PRIMARY KEY (run_id, source, company_id, reason)
);
CREATE INDEX IF NOT EXISTS idx_attention_snap_ts ON attention_snapshots(ts);
CREATE INDEX IF NOT EXISTS idx_attention_snap_company ON attention_snapshots(company_id);

CREATE TABLE IF NOT EXISTS stale_runs (
	run_id      TEXT PRIMARY KEY,
	ts          TEXT NOT NULL,
	total       INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_stale_runs_ts ON stale_runs(ts);

CREATE TABLE IF NOT EXISTS stale_backup_sets_snapshots (
	run_id            TEXT NOT NULL,
	ts                TEXT NOT NULL,
	reseller          TEXT NOT NULL DEFAULT '',
	company           TEXT NOT NULL DEFAULT '',
	backup_account    TEXT NOT NULL DEFAULT '',
	backup_set        TEXT NOT NULL DEFAULT '',
	last_complete_at  TEXT NOT NULL DEFAULT '',
	days_stale        REAL NOT NULL DEFAULT 0,
	engine            TEXT NOT NULL DEFAULT '',
	owner             TEXT NOT NULL DEFAULT '',
	raw               TEXT NOT NULL,
	PRIMARY KEY (run_id, backup_set, backup_account)
);
CREATE INDEX IF NOT EXISTS idx_stale_snap_ts ON stale_backup_sets_snapshots(ts);
CREATE INDEX IF NOT EXISTS idx_stale_snap_company ON stale_backup_sets_snapshots(company);
CREATE INDEX IF NOT EXISTS idx_stale_snap_engine ON stale_backup_sets_snapshots(engine);
CREATE INDEX IF NOT EXISTS idx_stale_snap_days ON stale_backup_sets_snapshots(days_stale);

CREATE TABLE IF NOT EXISTS dirty_runs (
	run_id      TEXT PRIMARY KEY,
	ts          TEXT NOT NULL,
	total       INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_dirty_runs_ts ON dirty_runs(ts);

CREATE TABLE IF NOT EXISTS dirty_repos_snapshots (
	run_id       TEXT NOT NULL,
	ts           TEXT NOT NULL,
	repo_id      TEXT NOT NULL DEFAULT '',
	company_id   TEXT NOT NULL DEFAULT '',
	company_name TEXT NOT NULL DEFAULT '',
	dirty_since  TEXT NOT NULL DEFAULT '',
	raw          TEXT NOT NULL,
	PRIMARY KEY (run_id, repo_id)
);
CREATE INDEX IF NOT EXISTS idx_dirty_snap_ts ON dirty_repos_snapshots(ts);
`

// EnsureNovelTables creates the snapshot tables if they don't exist. Idempotent.
// Safe to call from any novel command before reading or writing snapshots.
func (s *Store) EnsureNovelTables(ctx context.Context) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	for _, stmt := range strings.Split(novelSchemaSQL, ";") {
		stmt = strings.TrimSpace(stmt)
		if stmt == "" {
			continue
		}
		if _, err := s.db.ExecContext(ctx, stmt); err != nil {
			return fmt.Errorf("ensure novel tables: %w", err)
		}
	}
	return nil
}

// AttentionSnapshotRow is one row about a company that needs attention.
type AttentionSnapshotRow struct {
	Source      string          // 'admin_attention' | 'dirty_repos' | 'draas_in_progress' | 'open_issues'
	CompanyID   string          // may be empty
	CompanyName string          // may be empty
	ResellerID  string          // may be empty
	Score       int             // higher = more attention-worthy (default 1)
	Reason      string          // human-readable
	Raw         json.RawMessage // source object verbatim
}

// WriteAttentionSnapshot atomically records one attention-run + N rows.
// Returns the assigned run_id (timestamp-derived).
func (s *Store) WriteAttentionSnapshot(ctx context.Context, reseller string, rows []AttentionSnapshotRow) (string, error) {
	if err := s.EnsureNovelTables(ctx); err != nil {
		return "", err
	}
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	now := time.Now().UTC()
	runID := now.Format("20060102T150405.000Z")
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return "", fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback() }()
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO attention_runs(run_id, ts, total, reseller) VALUES(?, ?, ?, ?)`,
		runID, now.Format(time.RFC3339Nano), len(rows), reseller); err != nil {
		return "", fmt.Errorf("insert run: %w", err)
	}
	stmt, err := tx.PrepareContext(ctx,
		`INSERT OR REPLACE INTO attention_snapshots
		 (run_id, ts, source, company_id, company_name, reseller_id, score, reason, raw)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`)
	if err != nil {
		return "", fmt.Errorf("prepare row: %w", err)
	}
	defer stmt.Close()
	for _, r := range rows {
		raw := string(r.Raw)
		if raw == "" {
			raw = "null"
		}
		if _, err := stmt.ExecContext(ctx, runID, now.Format(time.RFC3339Nano), r.Source,
			r.CompanyID, r.CompanyName, r.ResellerID, r.Score, r.Reason, raw); err != nil {
			return "", fmt.Errorf("insert snapshot row: %w", err)
		}
	}
	if err := tx.Commit(); err != nil {
		return "", fmt.Errorf("commit: %w", err)
	}
	return runID, nil
}

// StaleSnapshotRow is one row of stale-backup-sets.
type StaleSnapshotRow struct {
	Reseller       string
	Company        string
	BackupAccount  string
	BackupSet      string
	LastCompleteAt string
	DaysStale      float64
	Engine         string
	Owner          string
	Raw            json.RawMessage
}

// WriteStaleSnapshot records the contents of a /reports/stale-backup-sets/ pull.
func (s *Store) WriteStaleSnapshot(ctx context.Context, rows []StaleSnapshotRow) (string, error) {
	if err := s.EnsureNovelTables(ctx); err != nil {
		return "", err
	}
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	now := time.Now().UTC()
	runID := now.Format("20060102T150405.000Z")
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return "", err
	}
	defer func() { _ = tx.Rollback() }()
	if _, err := tx.ExecContext(ctx,
		`INSERT INTO stale_runs(run_id, ts, total) VALUES(?, ?, ?)`,
		runID, now.Format(time.RFC3339Nano), len(rows)); err != nil {
		return "", err
	}
	stmt, err := tx.PrepareContext(ctx,
		`INSERT OR REPLACE INTO stale_backup_sets_snapshots
		 (run_id, ts, reseller, company, backup_account, backup_set,
		  last_complete_at, days_stale, engine, owner, raw)
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
	if err != nil {
		return "", err
	}
	defer stmt.Close()
	for _, r := range rows {
		raw := string(r.Raw)
		if raw == "" {
			raw = "null"
		}
		if _, err := stmt.ExecContext(ctx, runID, now.Format(time.RFC3339Nano),
			r.Reseller, r.Company, r.BackupAccount, r.BackupSet,
			r.LastCompleteAt, r.DaysStale, r.Engine, r.Owner, raw); err != nil {
			return "", err
		}
	}
	if err := tx.Commit(); err != nil {
		return "", err
	}
	return runID, nil
}

// LatestRunIDs returns the most recent run IDs for the named snapshot table,
// up to `limit` (most recent first). table must be one of the run tables
// declared in novelSchemaSQL ("attention_runs" | "stale_runs" | "dirty_runs").
func (s *Store) LatestRunIDs(ctx context.Context, table string, limit int) ([]string, error) {
	switch table {
	case "attention_runs", "stale_runs", "dirty_runs":
	default:
		return nil, fmt.Errorf("invalid run table: %s", table)
	}
	if limit < 1 {
		limit = 2
	}
	q := fmt.Sprintf(`SELECT run_id FROM %s ORDER BY ts DESC LIMIT ?`, table)
	rows, err := s.db.QueryContext(ctx, q, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id)
	}
	return out, rows.Err()
}

// AttentionAt returns the attention rows captured by one specific run_id.
func (s *Store) AttentionAt(ctx context.Context, runID string) ([]AttentionSnapshotRow, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT source, company_id, company_name, reseller_id, score, reason, raw
		 FROM attention_snapshots WHERE run_id = ? ORDER BY score DESC, company_name ASC`, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []AttentionSnapshotRow
	for rows.Next() {
		var r AttentionSnapshotRow
		var rawStr string
		if err := rows.Scan(&r.Source, &r.CompanyID, &r.CompanyName, &r.ResellerID, &r.Score, &r.Reason, &rawStr); err != nil {
			return nil, err
		}
		r.Raw = json.RawMessage(rawStr)
		out = append(out, r)
	}
	return out, rows.Err()
}

// StaleAt returns stale-set rows from one specific run_id, optionally filtered.
type StaleFilter struct {
	Reseller string
	Company  string
	Engine   string
	Owner    string
	MinDays  float64
	Limit    int
}

func (s *Store) StaleAt(ctx context.Context, runID string, f StaleFilter) ([]StaleSnapshotRow, error) {
	q := strings.Builder{}
	q.WriteString(`SELECT reseller, company, backup_account, backup_set,
	                       last_complete_at, days_stale, engine, owner, raw
	               FROM stale_backup_sets_snapshots WHERE run_id = ?`)
	args := []any{runID}
	if f.Reseller != "" {
		q.WriteString(` AND reseller = ?`)
		args = append(args, f.Reseller)
	}
	if f.Company != "" {
		q.WriteString(` AND company = ?`)
		args = append(args, f.Company)
	}
	if f.Engine != "" {
		q.WriteString(` AND engine = ?`)
		args = append(args, f.Engine)
	}
	if f.Owner != "" {
		q.WriteString(` AND owner = ?`)
		args = append(args, f.Owner)
	}
	if f.MinDays > 0 {
		q.WriteString(` AND days_stale >= ?`)
		args = append(args, f.MinDays)
	}
	q.WriteString(` ORDER BY days_stale DESC, company ASC`)
	if f.Limit > 0 {
		q.WriteString(` LIMIT ?`)
		args = append(args, f.Limit)
	}
	rows, err := s.db.QueryContext(ctx, q.String(), args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []StaleSnapshotRow
	for rows.Next() {
		var r StaleSnapshotRow
		var rawStr string
		if err := rows.Scan(&r.Reseller, &r.Company, &r.BackupAccount, &r.BackupSet,
			&r.LastCompleteAt, &r.DaysStale, &r.Engine, &r.Owner, &rawStr); err != nil {
			return nil, err
		}
		r.Raw = json.RawMessage(rawStr)
		out = append(out, r)
	}
	return out, rows.Err()
}

// LatestStaleRunID returns the most recent stale_runs.run_id, or "" if none.
func (s *Store) LatestStaleRunID(ctx context.Context) (string, error) {
	ids, err := s.LatestRunIDs(ctx, "stale_runs", 1)
	if err != nil || len(ids) == 0 {
		return "", err
	}
	return ids[0], nil
}

// LatestAttentionRunID returns the most recent attention_runs.run_id, or "" if none.
func (s *Store) LatestAttentionRunID(ctx context.Context) (string, error) {
	ids, err := s.LatestRunIDs(ctx, "attention_runs", 1)
	if err != nil || len(ids) == 0 {
		return "", err
	}
	return ids[0], nil
}
